from typing import List

def polynomial_to_string(n: int, coeffs: List[int]) -> str:
    terms = []

    for i in range(n, -1, -1):
        coeff = coeffs[n - i]
        if coeff == 0:
            continue

        term_parts = []

        if abs(coeff) != 1 or i == 0:
            term_parts.append(str(abs(coeff)))

        if i > 1:
            term_parts.append('x^' + str(i))
        elif i == 1:
            term_parts.append('x')

        term = ''.join(term_parts)
        if coeff < 0:
            term = '-' + term
        elif i == n:
            term = term.lstrip('+')

        terms.append(term)

    return ''.join(terms)
